arguments.command:
curl -s -X POST https://api.linear.app/graphql -H 'Content-Type: application/json' -H 'Authorization: Bearer <TOKEN>' -d '{"query":"{ __type(name: \"Mutation\") { fields { name args { name type { name kind ofType { name kind ofType { name } } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)['data']
def t(a):
    tt=a['type']
    while tt and tt.get('kind') and not tt.get('name'):
        tt=tt.get('ofType')
    return tt.get('name') if tt else None
for f in d['__type']['fields']:
    if f['name'] in ('issueCreate','issueUpdate','issueRelationCreate','commentCreate','commentDelete'):
        print(f['name'], {a['name']: t(a) for a in f['args']})
"

